for sid in series_ids:
    url = f'https://fred.stlouisfed.org/graph/fredgraph.csv?id={sid}'
    try:
        resp = requests.get(url, timeout=15, headers={'User-Agent': 'Mozilla/5.0'})
        if resp.status_code == 200 and len(resp.text) > 100:
            lines = resp.text.strip().split('\n')
            print(f"\nFound for {sid}:")
            for line in lines:
                if '1949' in line:
                    print(line)
            break
    except:
        pass

# Let me also check the standard way BLS provides historical data
# Sometimes it's just in a different format
# Also let's check the raw data for 1949 in the dataset we have
