import requests

# Let me look at the BLS series data to find the NSA values
# Try to access the CU series data files

# First, get the series list to find the right series
url = "https://download.bls.gov/pub/time.series/CU/cu.series"
try:
    resp = requests.get(url, timeout=30, headers={'User-Agent': 'Mozilla/5.0'})
    if resp.status_code == 200:
        # Find series related to CPI-U not seasonally adjusted
        lines = resp.text.strip().split('\n')
        for line in lines[:20]:
            print(line)
        # Look for series codes that might match what we need
        print("\n\nSearching for relevant series codes...")
        for line in lines:
            # Look for All Urban Consumers, Not Seasonally Adjusted
            if 'CUUR0000SA' in line and 'NSA' in line:
                print(f"NSA series: {line[:100]}")
                break
            elif 'CUUR0000SA0' in line:
                print(f"Possible: {line[:100]}")
except Exception as e:
    print(f"Error: {e}")

